List<string> ids = ["msg-1", "msg-2"];
IEnumerable<object> boxed = ids; // OK: IEnumerable<out T>
// IList<object> broken = ids;  // compile error: IList<T> is invariant

Action<object> log = o => Console.WriteLine(o);
Action<string> logId = log; // OK: Action<in T>
logId("msg-1");

string[] names = ["alice", "bob"];
object[] objects = names;       // allowed: array covariance
// objects[0] = 42;              // ArrayTypeMismatchException at run time

List<string> list = ["alice"];
// List<object> bad = list;       // compile error: List<T> is invariant

// TS: structural typing, no out/in keywords
// ReadonlyArray<string> is treated covariantly in many positions.
// Function parameters were bivariant by default until strictFunctionTypes.

type Handler<T> = (value: T) => void;
// With strictFunctionTypes off, Handler<object> and Handler<string>
// may be considered compatible — NOT the C# rule.

interface IProducer<out T>
{
    T Read(); // OK — T only out
}

interface IConsumer<in T>
{
    void Accept(T value); // OK — T only in
}

// interface IBroken<out T> { void Write(T value); } // compile error — T in input position

IProducer<string> ps = new StringProducer();
IProducer<object> po = ps; // covariant assignment
